  "Get again": "Erneut holen",
  "Get": "Holen",
  "Getting {name}: {pct}%": "{name} wird geholt: {pct} %",
  "{name} is here: a {season} database. The game's latest season is {latest}, so a new game with it starts there, its players keeping their ages. Press Use for my next new game, then start a new game.": "{name} ist da: eine Datenbank für {season}. Die neueste Saison des Spiels ist {latest}, also startet ein neues Spiel damit dort, und die Spieler behalten ihr Alter. Drücke Für mein nächstes neues Spiel nutzen und starte dann ein neues Spiel.",
  "{name} is here, for {season}. Press Use for my next new game, then start a new game.": "{name} ist da, für {season}. Drücke Für mein nächstes neues Spiel nutzen und starte dann ein neues Spiel.",
  "{name} did not come: {why}": "{name} ist nicht angekommen: {why}",
  "The {total} database files go together: {files} is missing.": { "one": "Die {total} Datenbankdateien gehören zusammen: {files} fehlt.", "other": "Die {total} Datenbankdateien gehören zusammen: {files} fehlen." },
